    excess={'left':cx-h-x0,'top':cy-h-y0,'right':x1-cx-h,'bottom':y1-cy-h}
    return {'center':c,'halfSide':h,'nominalBox':[cx-h,cy-h,cx+h,cy+h],'savedSampleOffsets':offsets,'signedOutwardExcess':excess,'sampleExtremaFit':all(v<=0 for v in excess.values()),'halfPixelSupportOutwardExcess':{k:v+0.5 for k,v in excess.items()},'halfPixelSupportFit':all(v+0.5<=0 for v in excess.values())}
